#!/usr/bin/env python3
"""ERRORS3 analysis (registration planned/ERRORS3_PREREG.md). Reads out/errors3/*.jsonl (encounters out to 90 m sideways, with location),
computes collision risk with the RISK1 formula when GPS sideways error is worse downtown (urban canyon), prints verdicts, writes planned/errors3_results_table.md."""
import glob, json, math
R = [json.loads(l) for f in sorted(glob.glob('out/errors3/*.jsonl')) for l in open(f) if l.strip()]
METROS = ('houston', 'dfw'); ARMS = ('S1', 'A2'); K_RAD = math.sqrt(-2 * math.log(0.05)); K_VER = 1.96
DT = {'houston': (2748, -1616), 'dfw': (18814, -10895)}   # downtown centre in engine coordinates (OSM building extracts' centres: 29.7575, -95.3675 and 32.7825, -96.7975)
HALF = 1800                                                  # downtown box half-size (m): the OSM building extracts cover about +-1.8 km
H95_L2, V95_L2 = 8.0, 13.0                                   # ERRORS1 L2 (GPS standard average)
CANYON_RAW, CANYON_PROC = 47.8, 4.4                          # NASA Langley (Gutierrez et al. 2025), Columbus OH urban canyon, 95th-percentile horizontal error: raw / with MAPT
WING = (0.65, 0.25); BIG = (1.5, 0.3)
Phi = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
def band(d, W, s): return Phi((W - d) / s) - Phi((-W - d) / s) if s > 0 else (1.0 if abs(d) < W else 0.0)
def size(op): return WING if op == 'wing' else BIG
def down(m, x, y): c = DT[m]; return abs(x - c[0]) <= HALF and abs(y - c[1]) <= HALF
def risk(row, m, inside, outside, search=90):
    """expected collisions; inside / outside: 95 % sideways error (m) of each aircraft in / out of the downtown box; height error L2 everywhere"""
    sz = math.sqrt(2) * V95_L2 / K_VER; p = 0.0
    for opA, opB, dperp, dz, dh, vrel, x, y in row['enc']:
        if dh >= search: continue
        h95 = inside if down(m, x, y) else outside; sh = math.sqrt(2) * h95 / K_RAD; A, B = size(opA), size(opB)
        p += band(dperp, A[0] + B[0], sh) * band(dz, A[1] + B[1], sz)
    return p
def rows(m, a, c): return [r for r in R if r['metro'] == m and r['arm'] == a and r['check'] == c]
def rate(m, a, c, inside, outside, search=90): x = rows(m, a, c); return 1e5 * sum(risk(r, m, inside, outside, search) for r in x) / sum(r['flightHours'] for r in x)
def share_down(m, a, c, within=30): x = rows(m, a, c); n = sum(1 for r in x for e in r['enc'] if e[4] < within); d = sum(1 for r in x for e in r['enc'] if e[4] < within and down(m, e[6], e[7])); return d / n if n else float('nan')
P = []
def chk(name, ok, text): P.append((name, ok, text)); print('PASS' if ok else 'FAIL', name, text)
mc = [(m, a) for m in METROS for a in ARMS]
base = {k: rate(*k, 'NONE', H95_L2, H95_L2) for k in mc}
g1 = {k: rate(*k, 'NONE', CANYON_RAW, H95_L2) / base[k] - 1 for k in mc}
chk('G1', all(abs(v) < 0.05 for v in g1.values()), 'metro-wide risk change, no check, L2, downtown at urban-canyon error: ' + '; '.join(f'{m} {a} {100 * v:+.1f} %' for (m, a), v in g1.items()))
g2 = {k: share_down(*k, 'NONE') for k in mc}
chk('G2', all(v < 0.02 for v in g2.values()), 'share of encounters within 30 m that are downtown: ' + '; '.join(f'{m} {a} {100 * v:.2f} %' for (m, a), v in g2.items()))
g3 = {k: rate(*k, 'NONE', CANYON_RAW, CANYON_RAW) / base[k] - 1 for k in mc}
chk('G3', all(abs(v) <= 0.25 for v in g3.values()), 'risk change, no check, if every place had urban-canyon sideways error: ' + '; '.join(f'{m} {a} {100 * v:+.0f} %' for (m, a), v in g3.items()))
b2 = {k: rate(*k, 'V2', H95_L2, H95_L2) for k in mc}; g4 = {k: rate(*k, 'V2', CANYON_RAW, CANYON_RAW) / b2[k] - 1 if b2[k] else float('nan') for k in mc}
chk('G4', all(v >= 0.5 for v in g4.values()), 'residual risk change with V2 if every place had urban-canyon sideways error (lower bound, 90 m search): ' + '; '.join(f'{m} {a} {100 * v:+.0f} %' for (m, a), v in g4.items()))
npass = sum(1 for _, ok, _ in P if ok)
T = ['# ERRORS3 results table (generated by planned/errors3_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Rows: {len(R)}; encounters: {sum(len(r["enc"]) for r in R)}.', '']
T += [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
T += ['', '## Collision risk per 100,000 flight hours at L2 (height error L2 everywhere), by sideways error case', '', '| Metro | Arm | Check | L2 everywhere (30 m search, = RISK1/2) | L2 everywhere (90 m search) | Downtown canyon raw (47.8 m) | Downtown canyon processed (4.4 m) | Canyon raw everywhere |', '|---|---|---|---|---|---|---|---|']
for m in METROS:
    for a in ARMS:
        for c in ('NONE', 'V2'):
            T.append(f'| {m} | {a} | {c} | {rate(m, a, c, H95_L2, H95_L2, 30):.3g} | {rate(m, a, c, H95_L2, H95_L2):.3g} | {rate(m, a, c, CANYON_RAW, H95_L2):.3g} | {rate(m, a, c, CANYON_PROC, H95_L2):.3g} | {rate(m, a, c, CANYON_RAW, CANYON_RAW):.3g} |')
T += ['', '## Encounters downtown', '', '| Metro | Arm | Check | Within 30 m: downtown share | Downtown encounters within 30 m (10 seeds) |', '|---|---|---|---|---|']
for m in METROS:
    for a in ARMS:
        for c in ('NONE', 'V2'):
            x = rows(m, a, c); d = sum(1 for r in x for e in r['enc'] if e[4] < 30 and down(m, e[6], e[7])); T.append(f'| {m} | {a} | {c} | {100 * share_down(m, a, c):.2f} % | {d} |')
open('planned/errors3_results_table.md', 'w').write('\n'.join(T) + '\n'); print(f'{npass} of {len(P)} passed')
